162: /**
163:  * The nearest ancestor of `scope` that holds an `.harness/adapters` directory —
164:  * the project root that owns the adapter manifest. Team worker artifact scopes
165:  * live under `.harness/missions/<team>/team/artifacts/...`, so resolving from
166:  * the scope itself is how the manifest went missing.
167:  */
168: export async function resolveAdapterRoot(scope: string): Promise<string> {
169:   const start = path.resolve(scope);
170:   for (let dir = start; ; ) {
171:     try {
172:       const stat = await lstat(path.join(dir, ".harness", "adapters"));
173:       if (stat.isDirectory()) return dir;
174:     } catch (error) {
175:       if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
176:     }
177:     const parent = path.dirname(dir);
178:     if (parent === dir) break;
179:     dir = parent;
180:   }
181:   throw new Error(
182:     `no .harness/adapters directory found above ${start}; the adapter manifest cannot be resolved from the project root`,
183:   );
184: }
