186: /**
187:  * Resolve a run id (exact or a unique prefix) through the live-run registry and
188:  * the bounded harness scan, so a team worker's artifact root is never something
189:  * the operator has to type.
190:  */
191: export async function resolveResumableRun(
192:   root: string,
193:   runRef: string,
194:   deps: ResolveRunDeps = {},
195: ): Promise<ResumableRun> {
196:   assertValidRunId(runRef);
197:   const projectRoot = (await findProjectRoot(root)) ?? path.resolve(root);
198:   const runs = await discoverRuns(projectRoot, { includeSettled: true, persist: false });
199:   const exact = runs.find((record) => record.run_id === runRef);
200:   const matches = exact ? [exact] : runs.filter((record) => record.run_id.startsWith(runRef));
201:   if (matches.length === 0) throw new Error(`run ${runRef} was not found from ${projectRoot}`);
202:   if (matches.length > 1) {
203:     throw new Error(`run reference ${runRef} is ambiguous: ${matches.map((record) => record.run_id).join(", ")}`);
204:   }
205:   const record = matches[0]!;
206:   const artifactRoot = runRootForRecord(projectRoot, record);
207:   const adapterRoot = await resolveAdapterRoot(artifactRoot);
208:   const processes = deps.processes ?? (await defaultProcessLister());
209:   const now = deps.now ?? Date.now();
210:   return {
211:     runId: record.run_id,
212:     missionId: record.mission_id,
213:     runtime: record.runtime,
214:     artifactRoot,
215:     adapterRoot,
216:     missionPath: path.join(artifactRoot, ".harness", "missions", record.mission_id, "mission.yaml"),
217:     ...(record.session_id !== undefined ? { sessionId: record.session_id } : {}),
218:     ...(record.stop_code !== undefined ? { stopCode: record.stop_code } : {}),
219:     ...(record.status !== undefined ? { status: record.status } : {}),
220:     liveness: liveness(record, processes, { now }),
221:   };
222: }
