228: /**
229:  * Validate everything a steer needs before anything is written: a non-empty
230:  * message, a runtime with a native resume path, a recorded native session id,
231:  * and an adapter manifest that resolves from the project root. Any failure
232:  * refuses and leaves the run untouched.
233:  */
234: export async function assertSteerable(target: ResumableRun, message: string): Promise<void> {
235:   if (message.trim().length === 0) throw new Error("steer requires a non-empty message");
236:   assertResumableRuntime(target.runtime);
237:   if (!target.sessionId) {
238:     throw new Error(`run ${target.runId} has no recorded native session id and cannot be steered; it would restart from scratch`);
239:   }
240:   try {
241:     await runtimeRegistry.load(target.adapterRoot, target.runtime);
242:   } catch (error) {
243:     throw new Error(
244:       `the ${target.runtime} adapter manifest does not resolve from the project root ${target.adapterRoot}: ${(error as Error).message}`,
245:     );
246:   }
247: }
248: 
249: /** A resume only ever overlays a settled attempt. A live one is steered instead. */
250: function assertSettledForResume(target: ResumableRun): void {
251:   if (target.liveness === "settled") return;
252:   if (target.liveness === "live") {
253:     throw new Error(
254:       `run ${target.runId} is still live; use "uh steer ${target.runId} \\"<message>\\"" to message it, or wait for it to settle`,
255:     );
256:   }
257:   throw new Error(`run ${target.runId} is ${target.liveness}; settle it before resuming (uh kill ${target.runId})`);
258: }
