260: /** Write the steer request next to the run's control file for its controller to consume. */
261: async function writeSteerRequest(target: ResumableRun, message: string, report: boolean): Promise<void> {
262:   const artifacts = await getMissionArtifactContext(target.artifactRoot, target.missionPath, target.runId);
263:   if (!artifacts) {
264:     throw new Error(`mission ${target.missionId} is not a canonical UH artifact directory; cannot write a steer request`);
265:   }
266:   const request = RuntimeSteerRequestSchema.parse({
267:     schema_version: "uh.runtime-steer-request.v0",
268:     mission_id: target.missionId,
269:     run_id: target.runId,
270:     message,
271:     report,
272:     requested_at: new Date().toISOString(),
273:   });
274:   await writeArtifactFile(artifacts.missionDir, path.join(artifacts.runDir, "steer-request.json"), JSON.stringify(request, null, 2));
275: }
