277: /**
278:  * Start a new run for the same mission, in the same artifact root and sandbox,
279:  * bound to `resume_from_run`. Records the operator lineage in both directions.
280:  */
281: async function performResume(
282:   target: ResumableRun,
283:   options: { notes: string; report: boolean; cancelled: boolean },
284:   deps: SteerDeps,
285: ): Promise<ResumeResult> {
286:   const runId = (deps.newRunId ?? generateRunId)();
287:   assertValidRunId(runId);
288:   const outcome = await deps.run({
289:     artifactRoot: target.artifactRoot,
290:     adapterRoot: target.adapterRoot,
291:     missionId: target.missionId,
292:     missionPath: target.missionPath,
293:     runtime: target.runtime,
294:     sourceRunId: target.runId,
295:     runId,
296:     recoveryNotes: options.notes,
297:     report: options.report,
298:   });
299:   const finalRunId = outcome?.runId ?? runId;
300:   await recordResumeLinks(target, finalRunId, options.report);
301:   return {
302:     runId: finalRunId,
303:     sourceRunId: target.runId,
304:     missionId: target.missionId,
305:     runtime: target.runtime,
306:     report: options.report,
307:     cancelled: options.cancelled,
308:     origin: "operator",
309:   };
310: }
311: 
312: async function recordResumeLinks(target: ResumableRun, newRunId: string, report: boolean): Promise<void> {
313:   const newArtifacts = await getMissionArtifactContext(target.artifactRoot, target.missionPath, newRunId);
314:   const sourceArtifacts = await getMissionArtifactContext(target.artifactRoot, target.missionPath, target.runId);
315:   if (!newArtifacts || !sourceArtifacts) {
316:     throw new Error(`mission ${target.missionId} is not a canonical UH artifact directory; cannot record the resume link`);
317:   }
318:   const createdAt = new Date().toISOString();
319:   const forward = ResumeLinkSchema.parse({
320:     schema_version: "uh.resume-link.v0",
321:     mission_id: target.missionId,
322:     run_id: newRunId,
323:     runtime: target.runtime,
324:     resume_origin: "operator",
325:     resumed_from: target.runId,
326:     report,
327:     created_at: createdAt,
328:   });
329:   const backward = ResumeLinkSchema.parse({
330:     schema_version: "uh.resume-link.v0",
331:     mission_id: target.missionId,
332:     run_id: target.runId,
333:     runtime: target.runtime,
334:     resume_origin: "operator",
335:     resumed_by: newRunId,
336:     report,
337:     created_at: createdAt,
338:   });
339:   await writeArtifactFile(newArtifacts.missionDir, path.join(newArtifacts.runDir, "resume-link.json"), JSON.stringify(forward, null, 2));
340:   await writeArtifactFile(sourceArtifacts.missionDir, path.join(sourceArtifacts.runDir, "resume-link.json"), JSON.stringify(backward, null, 2));
341: }
342: 
343: export interface ResumeOptions {
344:   notes?: string;
345: }
346: 
347: /**
348:  * `uh resume` — continue a settled run's native session as a new attempt.
349:  * Refuses a live run (steer it), an ambiguous reference, and a runtime with no
350:  * session resume.
351:  */
352: export async function resumeRun(
353:   root: string,
354:   runRef: string,
355:   options: ResumeOptions,
356:   deps: SteerDeps,
357: ): Promise<ResumeResult> {
358:   const target = await resolveResumableRun(root, runRef, resolveDeps(deps));
359:   assertResumableRuntime(target.runtime);
360:   assertSettledForResume(target);
361:   const notes = (options.notes ?? "").trim() || DEFAULT_OPERATOR_RESUME_NOTE;
362:   return performResume(target, { notes, report: false, cancelled: false }, deps);
363: }
364: 
365: export interface SteerOptions {
366:   report?: boolean;
367: }
368: 
369: /**
370:  * `uh steer` — message a run. A live run is steered by its owning controller:
371:  * the request is written for the controller's recovery loop, which stops the
372:  * attempt (`steered`) and resumes the same native session. A run with no live
373:  * controller falls back to cancelling it here and resuming the session
374:  * directly. Everything is validated before the run is touched.
375:  */
376: export async function steerRun(
377:   root: string,
378:   runRef: string,
379:   message: string,
380:   options: SteerOptions,
381:   deps: SteerDeps,
382: ): Promise<SteerResult> {
383:   const target = await resolveResumableRun(root, runRef, resolveDeps(deps));
384:   await assertSteerable(target, message);
385:   const report = options.report === true;
386:   if (target.liveness === "live") {
387:     await writeSteerRequest(target, message.trim(), report);
388:     // Signal the attempt to stop; the owning controller consumes the request
389:     // and resumes the session, so no new run is started here.
390:     await deps.cancel(root, target.missionId, target.runId);
391:     return { ok: true, mode: "controller", sourceRunId: target.runId, missionId: target.missionId, runtime: target.runtime, report };
392:   }
393:   const cancelled = target.liveness !== "settled";
394:   if (cancelled) await deps.cancel(root, target.missionId, target.runId);
395:   const resume = await performResume(target, { notes: steerNotes(message, report), report, cancelled }, deps);
396:   return {
397:     ok: true,
398:     mode: "fallback",
399:     sourceRunId: resume.sourceRunId,
400:     missionId: resume.missionId,
401:     runtime: resume.runtime,
402:     report,
403:     runId: resume.runId,
404:   };
405: }
406: 
407: function resolveDeps(deps: SteerDeps): ResolveRunDeps {
408:   return {
409:     ...(deps.processes !== undefined ? { processes: deps.processes } : {}),
410:     ...(deps.now !== undefined ? { now: deps.now } : {}),
411:   };
412: }

