17: /**
18:  * Whether a resume consumes the policy's automatic `max_resumes` budget.
19:  * Operator-initiated resumes are authorized outside the loop and never do.
20:  */
21: export function resumeConsumesBudget(origin: ResumeOrigin): boolean {
22:   return origin !== "operator";
23: }
