25: /** Automatic resume budget left after prior resumes, counting only budget-consuming ones. */
26: export function remainingResumeBudget(maxResumes: number, origins: readonly ResumeOrigin[]): number {
27:   return Math.max(0, maxResumes - origins.filter(resumeConsumesBudget).length);
28: }
