34: export const REPORT_REQUEST = `Before anything else, write a status report for the operator in exactly this shape:
35: 1. Done so far
36: 2. In progress
37: 3. Blocked on
38: 4. Next three actions
39: 5. Files touched
40: Write the report first, then continue your work.`;
