64: /** A preserved transcript is not permission to overlap or replay an unsettled attempt. */
65: export async function prepareRuntimeResume(root: string, missionId: string, runId: string, runtime: string, notes: string, origin: ResumeOrigin = "policy"): Promise<RuntimeResume> {
66:   assertSafeMissionId(missionId);
67:   assertValidRunId(runId);
68:   const suppliedNotes = notes.trim();
69:   if (!suppliedNotes) notes = "No additional deadline policy notes.";
70:   if (!notes.trim()) throw new Error("Resuming requires explicit recovery notes");
71:   const controlPath = path.join(root, ".harness", "missions", missionId, "runs", runId, "runtime-control.json");
72:   await lstat(controlPath);
73:   const artifacts = await getMissionArtifactContext(root, path.join(root, ".harness", "missions", missionId, "mission.yaml"), runId);
74:   if (!artifacts) throw new Error("Recovery source artifact context unavailable");
75:   for (const file of [controlPath, artifacts.runtimeSessionPath, artifacts.runtimeResultPath]) await assertWritableArtifact(artifacts.missionDir, file);
76:   const control = RuntimeControlSchema.parse(JSON.parse(await readFile(controlPath, "utf8")));
77:   if (control.mission_id !== missionId || control.run_id !== runId || control.runtime !== runtime) throw new Error("Recovery source identity mismatch");
78:   if (control.stop_code === "controller_lost") await reconcileRuntimeSettlement(root, missionId, runId);
79:   const session = RuntimeSessionSchema.parse(parse(await readFile(artifacts.runtimeSessionPath, "utf8")));
80:   const result = RuntimeResultSchema.parse(parse(await readFile(artifacts.runtimeResultPath, "utf8")));
81:   if (session.mission_id !== missionId || session.runtime !== runtime || result.mission_id !== missionId || result.runtime !== runtime) {
82:     throw new Error("Recovery source identity mismatch");
83:   }
84:   if (control.status === "running" || session.status === "running" || session.status === "planned") throw new Error("Previous attempt must be fully settled before resuming");
85:   if (control.stop_code === "policy" || control.stop_code === "route_mismatch" || control.stop_code === "route_unverified") throw new Error("Policy-stopped attempts cannot be automatically resumed");
86:   if (!control.session_id) throw new Error("Previous attempt did not record a native session id; refusing to restart from scratch");
87:   const sourceStopReason = control.stop_reason ?? control.stop_code;
88:   const grace = control.stop_code === "deadline";
89:   const combinedNotes = grace
90:     ? `${notes}\nYour time budget is exhausted. Write your deliverable now with everything you have found so far. Mark it clearly as INCOMPLETE at the top, and end it with a section titled "Missing for the next step" listing what you did not get to and where you stopped. Do not start new investigation. Then stop.`
91:     : `${notes}\nYou were stopped: ${sourceStopReason}. Do not repeat that action. Inspect existing outputs before continuing.`;
92:   return { sourceRunId: runId, sessionId: control.session_id, notes: combinedNotes, sourceStopCode: control.stop_code, sourceStopReason, grace, origin };
