154: /** Own the bounded recovery loop within the invoking CLI, not a detached second controller. */
155: export async function runWithRuntimeRecovery<T extends RecoverableRuntimeResult>(input: {
156:   root: string;
157:   missionId: string;
158:   runtime: string;
159:   runId: string;
160:   recovery?: unknown;
161:   extraRuntimeConfigOverrides?: Record<string, unknown>;
162:   cancellationSignal?: AbortSignal;
163:   onAttempt?: (runId: string) => Promise<void>;
164:   /**
165:    * Resumes that already produced the attempt this loop starts from. Operator
166:    * resumes are free: they never reduce the automatic `max_resumes` budget.
167:    */
168:   priorResumeOrigins?: readonly ResumeOrigin[];
169:   run: (options: RecoveryRunOptions) => Promise<T>;
170: }): Promise<T> {
171:   const policy = input.recovery === undefined ? undefined : RuntimeRecoveryPolicySchema.parse(input.recovery);
172:   if (policy && !["oh-my-pi", "command-code", "claude-code"].includes(input.runtime)) throw new Error("This runtime does not implement native bounded session recovery");
173:   let runId = input.runId;
174:   let overrides = input.extraRuntimeConfigOverrides;
175:   let graceAttempted = false;
176:   // Prior resumes already spent part of the budget; operator resumes spent none.
177:   for (let resumed = (input.priorResumeOrigins ?? []).filter(resumeConsumesBudget).length; ; resumed++) {
178:     await input.onAttempt?.(runId);
179:     let result = await input.run({ runId, extraRuntimeConfigOverrides: overrides });
180:     // A `uh steer` request is an operator message to a live attempt. The
181:     // controller stops the steered attempt and resumes its native session with
182:     // the message as the first instruction. It is free: it never spends the
183:     // automatic `max_resumes` budget and works without a recovery policy.
184:     for (;;) {
185:       if (input.cancellationSignal?.aborted) return result;
186:       const steer = await consumeSteerRequest(input.root, input.missionId, runId);
187:       if (!steer || result.result?.status === "passed") break;
188:       const notes = steerNotes(steer.message, steer.report);
189:       try {
190:         await prepareRuntimeResume(input.root, input.missionId, runId, input.runtime, notes, "operator");
191:       } catch {
192:         // The attempt cannot be resumed (for example a concurrent policy stop);
193:         // it is left settled rather than relabelled or restarted from scratch.
194:         break;
195:       }
196:       await markAttemptSteered(input.root, input.missionId, runId, steer.message);
197:       overrides = { ...input.extraRuntimeConfigOverrides, resume_session: undefined, resume_from_run: runId, recovery_notes: notes };
198:       runId = generateRunId();
199:       await input.onAttempt?.(runId);
200:       result = await input.run({ runId, extraRuntimeConfigOverrides: overrides });
201:     }
202:     if (!policy || input.cancellationSignal?.aborted || result.result?.status === "passed") return result;
203:     const control = RuntimeControlSchema.parse(JSON.parse(await readFile(path.join(input.root, ".harness", "missions", input.missionId, "runs", runId, "runtime-control.json"), "utf8")));
204:     if (graceAttempted) return result;
205:     if (policy.on_deadline && control.stop_code === "deadline" && control.session_id) {
206:       const notes = policy.on_deadline.notes ?? policy.notes;
207:       await prepareRuntimeResume(input.root, input.missionId, runId, input.runtime, notes);
208:       overrides = {
209:         ...input.extraRuntimeConfigOverrides,
210:         resume_session: undefined,
211:         resume_from_run: runId,
212:         recovery_notes: notes,
213:         recovery_grace: true,
214:       };
215:       runId = generateRunId();
216:       graceAttempted = true;
217:       continue;
218:     }
219:     if (resumed >= policy.max_resumes || !control.stop_code || !["startup", "stall", "timeout", "repeated_failure", "denial_budget"].includes(control.stop_code) || !control.session_id) return result;
220:     const resume = await prepareRuntimeResume(input.root, input.missionId, runId, input.runtime, policy.notes);
221:     overrides = { ...input.extraRuntimeConfigOverrides, resume_session: undefined, resume_from_run: runId, recovery_notes: policy.notes };
222:     runId = generateRunId();
223:   }
224: }
