19: function manualClock() {
20:   let current = Date.now();
21:   const polls: Array<() => void> = [];
22:   return {
23:     now: () => current,
24:     setInterval: (callback: () => void) => { polls.push(callback); return polls.length; },
25:     clearInterval: () => {},
26:     advance: (milliseconds: number) => { current += milliseconds; for (const poll of [...polls]) poll(); },
