168:   const relative = relativeArtifactPath(projectRoot, artifactRoot);
169:   const match = /^\.harness\/missions\/([^/]+)\/team\/artifacts\/[^/]+\/workers\/([^/]+)$/.exec(relative);
170:   return match ? { mission_id: match[1], role: match[2] } : undefined;
