178: function settledTime(record: { settled_at?: string; heartbeat_at?: string }): number | undefined {
179:   const raw = record.settled_at ?? record.heartbeat_at;
180:   if (raw === undefined) return undefined;
181:   const parsed = Date.parse(raw);
182:   return Number.isFinite(parsed) ? parsed : undefined;
183: }
