185: export function heartbeatAgeMs(record: { heartbeat_at?: string }, now: number): number | undefined {
186:   if (record.heartbeat_at === undefined) return undefined;
187:   const parsed = Date.parse(record.heartbeat_at);
188:   return Number.isFinite(parsed) ? Math.max(0, now - parsed) : undefined;
189: }
