211:   const artifactRoot = path.resolve(input.artifactRoot);
212:   const controlPath = input.controlPath !== undefined
213:     ? path.resolve(input.controlPath)
214:     : path.join(artifactRoot, ".harness", "missions", input.missionId, "runs", input.runId, "runtime-control.json");
215:   const entry: LiveRunEntry = LiveRunEntrySchema.parse({
216:     schema_version: LIVE_RUN_SCHEMA_VERSION,
