218:     mission_id: input.missionId,
219:     runtime: input.runtime,
220:     ...(input.model !== undefined ? { model: input.model } : {}),
221:     ...(input.team !== undefined ? { team: input.team } : {}),
222:     artifact_root: relativeOrDot(projectRoot, artifactRoot),
223:     control_path: relativeOrDot(projectRoot, controlPath),
224:     controller_pid: input.controllerPid ?? process.pid,
225:     started_at: input.startedAt ?? new Date().toISOString(),
