307: async function readRegistry(projectRoot: string): Promise<LiveRunEntry[]> {
308:   const directory = liveRunsDir(projectRoot);
309:   let names: string[];
310:   try {
311:     names = await readdir(directory);
312:   } catch {
313:     return [];
314:   }
315:   const entries: LiveRunEntry[] = [];
316:   for (const name of names.filter((name) => name.endsWith(".json"))) {
317:     try {
318:       const parsed = LiveRunEntrySchema.safeParse(JSON.parse(await readFile(path.join(directory, name), "utf8")));
319:       if (parsed.success) entries.push(parsed.data);
320:     } catch {
321:       // A malformed registry entry must not hide the rest of the directory.
322:     }
323:   }
324:   return entries;
325: }
