327: async function readControlFile(projectRoot: string, controlPathRel: string): Promise<RuntimeControl | undefined> {
328:   try {
329:     const parsed = RuntimeControlSchema.safeParse(JSON.parse(await readFile(path.resolve(projectRoot, controlPathRel), "utf8")));
330:     return parsed.success ? parsed.data : undefined;
331:   } catch {
332:     return undefined;
333:   }
