336: /** Read only the tail of events.ndjson for the last event time and tool name. */
337: async function readEventsTail(
338:   projectRoot: string,
339:   controlPathRel: string,
340: ): Promise<{ lastEventAt?: string; lastTool?: string }> {
341:   const eventsPath = path.join(path.dirname(path.resolve(projectRoot, controlPathRel)), "events.ndjson");
342:   let handle;
343:   try {
344:     handle = await open(eventsPath, "r");
345:   } catch {
346:     return {};
347:   }
348:   try {
349:     const { size } = await handle.stat();
350:     if (size === 0) return {};
351:     const length = Math.min(size, EVENTS_TAIL_BYTES);
352:     const buffer = Buffer.allocUnsafe(length);
353:     const { bytesRead } = await handle.read(buffer, 0, length, size - length);
354:     let text = buffer.subarray(0, bytesRead).toString("utf8");
355:     if (size > length) {
356:       const newline = text.indexOf("\n");
357:       text = newline >= 0 ? text.slice(newline + 1) : "";
358:     }
359:     let lastEventAt: string | undefined;
360:     let lastTool: string | undefined;
361:     for (const line of text.split("\n")) {
362:       const trimmed = line.trim();
363:       if (trimmed.length === 0) continue;
364:       let event: Record<string, unknown>;
365:       try {
366:         const parsed = JSON.parse(trimmed) as unknown;
367:         if (parsed === null || typeof parsed !== "object") continue;
368:         event = parsed as Record<string, unknown>;
369:       } catch {
370:         continue;
371:       }
372:       if (typeof event.timestamp === "string") lastEventAt = event.timestamp;
373:       const tool = event.toolName ?? event.tool_name ?? event.tool;
374:       if (typeof tool === "string" && tool.length > 0) lastTool = tool;
375:     }
376:     return {
377:       ...(lastEventAt !== undefined ? { lastEventAt } : {}),
378:       ...(lastTool !== undefined ? { lastTool } : {}),
379:     };
380:   } finally {
381:     await handle.close();
382:   }
383: }
