392: /** Depth-limited walk of `.harness/` for runtime-control.json files. */
393: async function scanForRuntimeControls(projectRoot: string): Promise<ScannedControl[]> {
394:   const found: ScannedControl[] = [];
395:   let visited = 0;
396:   const walk = async (directory: string, depth: number): Promise<void> => {
397:     if (depth > SCAN_MAX_DEPTH || visited >= SCAN_DIRECTORY_LIMIT) return;
398:     let entries;
399:     try {
400:       entries = await readdir(directory, { withFileTypes: true });
401:     } catch {
402:       return;
403:     }
404:     visited += 1;
405:     for (const entry of entries) {
406:       if (entry.name === "node_modules" || entry.name === ".git" || entry.name === "live-runs") continue;
407:       if (entry.isDirectory()) {
408:         await walk(path.join(directory, entry.name), depth + 1);
409:         continue;
410:       }
411:       if (entry.name !== "runtime-control.json") continue;
412:       const runDir = directory;
413:       const runId = path.basename(runDir);
414:       try {
415:         assertValidRunId(runId);
416:       } catch {
417:         continue;
418:       }
419:       const artifactRootAbs = path.resolve(runDir, "..", "..", "..", "..", "..");
420:       found.push({
421:         runId,
422:         controlPathRel: relativeArtifactPath(projectRoot, path.join(runDir, entry.name)),
423:         artifactRootAbs,
424:         artifactRootRel: relativeArtifactPath(projectRoot, artifactRootAbs),
425:       });
426:     }
427:   };
428:   await walk(path.join(projectRoot, ".harness"), 0);
429:   return found;
430: }
