493: /**
494:  * Every run discoverable from the project root: the registry unioned with a
495:  * bounded scan for pre-registry runtime-control.json files. Settled runs are
496:  * dropped unless `includeSettled`, and then only within the 24h retention
497:  * window. Terminal control facts are reconciled back into the registry.
498:  */
499: export async function discoverRuns(
500:   projectRoot: string,
501:   options: DiscoverRunsOptions = {},
502: ): Promise<LiveRunRecord[]> {
503:   const includeSettled = options.includeSettled === true;
504:   const now = options.now ?? Date.now();
505:   const persist = options.persist !== false;
506:   const records: LiveRunRecord[] = [];
507:   const seen = new Set<string>();
508:   for (const entry of await readRegistry(projectRoot)) {
509:     const record = await hydrateRegistryRecord(projectRoot, entry);
510:     if (persist && isSettled(record) && entry.settled_at === undefined) {
511:       await settleLiveRun(projectRoot, entry.run_id, {
512:         status: record.status,
513:         stop_code: record.stop_code,
514:         settled_at: record.heartbeat_at,
515:         controller_pid: record.controller_pid,
516:       }).catch(() => undefined);
517:     }
518:     seen.add(record.run_id);
519:     records.push(record);
520:   }
521:   for (const found of await scanForRuntimeControls(projectRoot)) {
522:     if (seen.has(found.runId)) continue;
523:     const record = await hydrateScannedRecord(projectRoot, found);
524:     if (record === undefined) continue;
525:     seen.add(record.run_id);
526:     records.push(record);
527:   }
528:   return records.filter((record) => {
529:     if (!isSettled(record)) return true;
530:     if (!includeSettled) return false;
531:     const at = settledTime(record);
532:     return at === undefined || now - at <= SETTLED_RETENTION_MS;
533:   });
534: }
