536: /* -------------------------------------------------------------------------- */
537: /* Liveness                                                                   */
538: /* -------------------------------------------------------------------------- */
539: 
540: /**
541:  * Verdict for a discovered run.
542:  *
543:  * - `settled`: terminal status (or an explicit settled_at).
544:  * - `orphaned`: the controller reports `running` but its pid is gone. This is
545:  *   the incident case and must be surfaced loudly.
546:  * - `stale`: the controller is alive but its heartbeat is older than twice the
547:  *   stall window.
548:  * - `live`: controller alive and running with a fresh heartbeat.
549:  */
550: export function liveness(
551:   record: LiveRunRecord,
552:   processes: readonly NativeProcess[],
553:   options: LivenessOptions = {},
554: ): LivenessVerdict {
555:   const now = options.now ?? Date.now();
556:   const stallWindowMs = options.stallWindowMs ?? DEFAULT_STALL_WINDOW_MS;
557:   if (isSettled(record)) return "settled";
558:   const running = record.status === undefined || record.status === "running";
559:   if (!running) return "unknown";
560:   if (!processes.some((process) => process.pid === record.controller_pid)) return "orphaned";
561:   const age = heartbeatAgeMs(record, now);
562:   if (age !== undefined && age > stallWindowMs * STALE_HEARTBEAT_MULTIPLIER) return "stale";
563:   return "live";
564: }
565: 
566: /** Native processes whose parent chain leads back to `controllerPid`. */
567: export function processChildren(controllerPid: number, processes: readonly NativeProcess[]): NativeProcess[] {
568:   const byParent = new Map<number, NativeProcess[]>();
569:   for (const process of processes) {
570:     const siblings = byParent.get(process.ppid) ?? [];
571:     siblings.push(process);
572:     byParent.set(process.ppid, siblings);
573:   }
574:   const children: NativeProcess[] = [];
575:   const seen = new Set<number>([controllerPid]);
576:   const stack = [controllerPid];
577:   while (stack.length > 0) {
578:     const pid = stack.pop()!;
579:     for (const child of byParent.get(pid) ?? []) {
580:       if (seen.has(child.pid)) continue;
581:       seen.add(child.pid);
582:       // The tree keeps only the first 80 characters of each command line.
583:       children.push({ ...child, command: child.command.slice(0, PROCESS_TREE_COMMAND_CHARS) });
584:       stack.push(child.pid);
585:     }
586:   }
587:   return children;
588: }
589: 
590: /** Default process lister: Windows CIM, else POSIX `ps`. Never throws. */
591: export async function defaultProcessLister(): Promise<NativeProcess[]> {
592:   try {
593:     return process.platform === "win32" ? await listWindowsProcesses() : await listPosixProcesses();
594:   } catch {
595:     return [];
596:   }
597: }
598: 
599: async function listWindowsProcesses(): Promise<NativeProcess[]> {
600:   const { stdout } = await execFileAsync("powershell.exe", [
601:     "-NoLogo", "-NoProfile", "-NonInteractive", "-Command",
602:     "Get-CimInstance Win32_Process | Select-Object ProcessId,ParentProcessId,Name,CommandLine | ConvertTo-Json -Compress -Depth 2",
603:   ], { windowsHide: true, maxBuffer: 64 * 1024 * 1024 });
604:   const trimmed = stdout.trim();
605:   if (trimmed.length === 0) return [];
606:   const parsed = JSON.parse(trimmed) as unknown;
607:   const rows = Array.isArray(parsed) ? parsed : [parsed];
608:   const processes: NativeProcess[] = [];
609:   for (const row of rows) {
610:     if (row === null || typeof row !== "object") continue;
611:     const record = row as Record<string, unknown>;
612:     const pid = Number(record.ProcessId);
613:     const ppid = Number(record.ParentProcessId);
614:     if (!Number.isFinite(pid)) continue;
615:     processes.push({
616:       pid,
617:       ppid: Number.isFinite(ppid) ? ppid : 0,
618:       name: typeof record.Name === "string" ? record.Name : "",
619:       command: (typeof record.CommandLine === "string" ? record.CommandLine : "").slice(0, PROCESS_COMMAND_PREVIEW_CHARS),
620:     });
621:   }
622:   return processes;
623: }
624: 
625: async function listPosixProcesses(): Promise<NativeProcess[]> {
626:   const { stdout } = await execFileAsync("ps", ["-eo", "pid,ppid,comm,args"], { maxBuffer: 64 * 1024 * 1024 });
627:   const processes: NativeProcess[] = [];
628:   for (const line of stdout.split("\n").slice(1)) {
629:     const match = /^\s*(\d+)\s+(\d+)\s+(\S+)\s*(.*)$/.exec(line);
630:     if (!match) continue;
631:     processes.push({
632:       pid: Number(match[1]),
633:       ppid: Number(match[2]),
634:       name: match[3],
635:       command: match[4].slice(0, PROCESS_COMMAND_PREVIEW_CHARS),
636:     });
637:   }
638:   return processes;
639: }
