645: /** Discover runs, attach liveness verdicts, and list the controller's tree. */
646: export async function listLiveRuns(
647:   projectRoot: string,
648:   options: ListLiveRunsOptions = {},
649: ): Promise<ListLiveRunsResult> {
650:   const now = options.now ?? Date.now();
651:   const records = await discoverRuns(projectRoot, {
652:     includeSettled: options.includeSettled,
653:     now,
654:     persist: options.persist,
655:   });
656:   let processes = options.processes;
657:   if (processes === undefined) {
658:     processes = records.some((record) => !isSettled(record)) ? await defaultProcessLister() : [];
659:   }
660:   const records_ = records.map((record): LiveRunView => {
661:     const age = heartbeatAgeMs(record, now);
662:     return {
663:       ...record,
664:       liveness: liveness(record, processes, { now, stallWindowMs: options.stallWindowMs }),
665:       children: processChildren(record.controller_pid, processes),
666:       ...(age !== undefined ? { heartbeat_age_ms: age } : {}),
667:     };
668:   });
669:   return { records: records_, orphaned: records_.filter((record) => record.liveness === "orphaned").length };
670: }
