704:       const heartbeat = formatAge(record.heartbeat_age_ms ?? heartbeatAgeMs(record, now));
705:       const lastAge = record.last_event_at !== undefined
706:         ? formatAge(now - Date.parse(record.last_event_at))
707:         : "-";
708:       const pids = [record.controller_pid, ...record.children.map((child) => child.pid)].join(",");
