114: /**
115:  * Guard before writing/overwriting an artifact: reject symlinks at the target
116:  * and every ancestor through the owning .harness directory.
117:  */
118: export async function assertWritableArtifact(missionDir: string, artifactPath: string): Promise<void> {
119:   assertPathInsideMissionDir(missionDir, artifactPath);
120:   const boundary = path.resolve(missionDir, "..", "..");
121:   for (let candidate = path.resolve(artifactPath); ; candidate = path.dirname(candidate)) {
122:     try {
123:       if ((await lstat(candidate)).isSymbolicLink()) {
124:         throw new Error(`Refusing to overwrite symlinked artifact: ${candidate}`);
125:       }
126:     } catch (error) {
127:       if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
128:     }
129:     if (path.relative(boundary, candidate) === "") return;
130:   }
131: }
