133: /** Refuse any artifact path that escapes the mission directory. */
134: export function assertPathInsideMissionDir(missionDir: string, artifactPath: string): void {
135:   const relative = path.relative(missionDir, path.resolve(artifactPath));
136:   if (relative.startsWith("..") || path.isAbsolute(relative) || relative === "") {
137:     throw new Error(`Refusing to write artifact outside mission directory: ${artifactPath}`);
138:   }
139: }
